//! Desktop binary: calls the `run()` entry point that `frus_shell::main!` generates
//! in the library. (On Android and the web there is no binary: the entry point is
//! `android_main` / `start`, both generated by the macro.)
//!
//! `cargo run -p frus-demo` (add `RUST_LOG=info` for logs).

#[cfg(not(any(target_os = "android", target_arch = "wasm32")))]
fn main() -> frus_shell::anyhow::Result<()> {
    frus_demo::run()
}

#[cfg(any(target_os = "android", target_arch = "wasm32"))]
fn main() {}
